export const recipes=[{id:'tacos',name:'Everyone’s taco night',image:'tacos',minutes:25,price:5.25,tag:'Easy to make your own',description:'Black bean tacos, crunchy vegetables, avocado, and plenty of lime. Put everything on the table and let everyone build their own.',why:'A vegetarian base for Maya, no dairy in the base for Jordan, and hot sauce on the side for Alex. Check ingredient labels for Riley’s peanut allergy.',ingredients:[['Black beans','2 cans','stock'],['Tortillas','12 pieces','list'],['Tomatoes','1 punnet','list'],['Avocados','2 pieces','new'],['Limes','3 pieces','new']],steps:['Warm the beans with cumin, a splash of water, and salt.','Chop tomatoes and avocado. Cut the limes into wedges.','Warm tortillas in a dry pan. Serve everything separately with hot sauce.']},{id:'salad',name:'A big, bright salad',image:'salad',minutes:20,price:4.5,tag:'A fridge-friendly lunch',description:'A flexible bowl of crisp greens, roasted chickpeas, cucumber, and lemon dressing. Add eggs or another protein at the table.',why:'Uses the greens already in the kitchen. Keep toppings separate so everyone can choose. The photo is illustrative; review all ingredients.',ingredients:[['Salad greens','1 bag','stock'],['Chickpeas','2 cans','new'],['Cucumber','1 piece','new'],['Lemon','1 piece','new']],steps:['Rinse chickpeas and crisp them in a pan with olive oil.','Chop cucumber and wash the greens.','Toss with lemon and olive oil, then add toppings individually.']},{id:'pasta',name:'Comfort in a bowl',image:'pasta',minutes:30,price:6,tag:'For a slow Sunday',description:'Lemon pasta with greens and a creamy sauce. Make the sauce with a suitable dairy-free alternative if the group prefers.',why:'A cozy option for a shared evening. Jordan prefers a dairy-free version; confirm that swap before adding ingredients. Photo shows a serving suggestion.',ingredients:[['Pasta','500 g','new'],['Salad greens','1 bag','stock'],['Lemon','1 piece','new'],['Oat cooking cream','200 ml','new']],steps:['Cook pasta in salted water; save a cup of cooking water.','Warm the cream and lemon zest, then fold in greens.','Toss pasta with sauce and a splash of pasta water. Serve hot.']}];
export const seed=()=>({version:1,actor:'alex',voting:true,matching:false,theme:'Movie night',saved:[],votes:{tacos:['maya','riley'],salad:['jordan'],pasta:[]},plans:[{id:'movie',name:'Movie night at ours.',date:'2026-10-17',time:'18:30',theme:'Movie night',members:people.map(p=>p.id),menu:null}],items:[{id:'i1',name:'Tortillas',quantity:'12 pieces',owner:'maya',store:'Safeway',members:people.map(p=>p.id),bought:false},{id:'i2',name:'Tomatoes',quantity:'1 punnet',owner:'maya',store:'Safeway',members:people.map(p=>p.id),bought:false},{id:'i3',name:'Oat milk',quantity:'1 carton',owner:'jordan',store:'Target',members:['jordan'],bought:false},{id:'i4',name:'Paper towels',quantity:'1 pack',owner:null,store:'Costco',members:people.map(p=>p.id),bought:false}],pantry:[{name:'Black beans',quantity:'2 cans',status:'Have',confirmed:'Oct 16'},{name:'Salad greens',quantity:'1 bag',status:'Use soon',confirmed:'Oct 16'},{name:'Rice',quantity:'1 bag',status:'Unsure',confirmed:'Oct 10'}],expenses:[{id:'e1',name:'Last week’s shared groceries',payer:'maya',cents:7400,members:people.map(p=>p.id),date:'Oct 12'}],payments:[],profiles:people.map(p=>({...p}))});
export function split(cents,ids){if(!Number.isSafeInteger(cents)||cents<0||!ids.length||new Set(ids).size!==ids.length)throw Error('Choose a valid amount and participants.');const base=Math.floor(cents/ids.length),remainder=cents%ids.length;return Object.fromEntries(ids.map((id,i)=>[id,base+(i<remainder?1:0)]));}
export function balance(state,actor){const debts={};for(const e of state.expenses){const shares=split(e.cents,e.members);if(e.payer===actor){for(const [id,n]of Object.entries(shares))if(id!==actor)debts[id]=(debts[id]||0)-n;}else if(shares[actor])debts[e.payer]=(debts[e.payer]||0)+shares[actor];}for(const p of state.payments.filter(p=>p.confirmed)){if(p.from===actor)debts[p.to]=(debts[p.to]||0)-p.cents;if(p.to===actor)debts[p.from]=(debts[p.from]||0)+p.cents;}return Object.entries(debts).filter(([,c])=>c!==0);}
export const normalize=s=>s.trim().toLowerCase().replace(/\s+/g,' ');
export function missingIngredients(state,recipe){return recipe.ingredients.map(([name,quantity])=>({name,quantity,stock:state.pantry.find(p=>normalize(p.name)===normalize(name)&&['Have','Use soon'].includes(p.status)),listed:state.items.find(i=>normalize(i.name)===normalize(name)&&!i.bought)}));}
export function addIngredients(state,recipe,members){if(!members.length)throw Error('Choose someone to share this meal.');let n=0;for(const item of missingIngredients(state,recipe)){if(!item.stock&&!item.listed){state.items.push({id:crypto.randomUUID(),name:item.name,quantity:item.quantity,owner:null,store:'Choose a store',members:[...members],bought:false});n++;}}return n;}
export const money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);
